<?php declare( strict_types=1 ); namespace Inc\Repositories\WPDBRepositories; use Inc\DTO\Exam\ExamReportDTO; use Inc\Enums\Settings\TableName; class ExamReportRepository { private \wpdb $wpdb; private string $table; public function __construct( ?\wpdb $wpdb = null ) { $this->wpdb = $wpdb ?? $GLOBALS['wpdb']; $this->table = TableName::ExamReports->prefixed(); } public function insert( array $data ): int { $this->wpdb->insert( $this->table, $data ); return (int) $this->wpdb->insert_id; } public function find( int $id ): ?ExamReportDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE id = %d", $this->table, $id ), ARRAY_A ); return $row ? ExamReportDTO::fromArray( $row ) : null; } public function findByEvent( int $eventId ): array { $rows = $this->wpdb->get_results( $this->wpdb->prepare( "SELECT * FROM %i WHERE event_id = %d AND revoked_at IS NULL", $this->table, $eventId ), ARRAY_A ); return array_map( [ ExamReportDTO::class, 'fromArray' ], $rows ?: [] ); } public function update( int $id, array $data ): bool { return false !== $this->wpdb->update( $this->table, $data, [ 'id' => $id ] ); } }
